const crypto = require('crypto');

const input = $input.first().json;
const payload = input.body || input;
const data = payload.data || payload;
const fields = Array.isArray(data.fields) ? data.fields : [];

const byLabel = {};
for (const field of fields) {
  const label = String(field.label || field.key || '').trim().toLowerCase();
  byLabel[label] = field.value;
}

// TODO(verify): confirm the real Tally labels/keys once the form is published.
// Matching is loose (lowercase substring) so small copy edits do not break it.
function pick() {
  const needles = Array.prototype.slice.call(arguments).map(function (n) { return String(n).toLowerCase(); });
  for (const needle of needles) {
    for (const label of Object.keys(byLabel)) {
      if (label.indexOf(needle) !== -1) return byLabel[label];
    }
  }
  return undefined;
}

function asArray(value) {
  if (value === undefined || value === null || value === '') return [];
  return Array.isArray(value) ? value : [value];
}

const orderCode = String(pick('codigo', 'code') || (data.hidden && data.hidden.code) || (payload.hiddenFields && payload.hiddenFields.code) || '').trim();
const responseId = String(data.responseId || data.submissionId || data.eventId || input.eventId || '').trim();

const nameA = String(pick('nombre a', 'name a', 'tu nombre') || '').trim();
const nameB = String(pick('nombre b', 'name b', 'su nombre') || '').trim();
const anniversaryRaw = pick('aniversario', 'fecha');
const youtubeUrl = String(pick('youtube', 'video') || '').trim();
const templateSlug = String(pick('plantilla', 'template') || 'midnight-letter').trim() || 'midnight-letter';

const messages = [];
for (const raw of asArray(pick('mensaje', 'message'))) {
  for (const part of String(raw).split('\n\n')) {
    const trimmed = part.trim();
    if (trimmed) messages.push(trimmed);
  }
}

const photos = asArray(pick('foto', 'photo', 'imagen'))
  .reduce(function (acc, value) { return acc.concat(asArray(value)); }, [])
  .map(function (value) {
    if (typeof value === 'string') return { url: value, alt: '' };
    return { url: value.url || value.downloadUrl || '', alt: value.name || value.alt || '' };
  })
  .filter(function (p) { return !!p.url; })
  .map(function (p, index) { return { url: p.url, alt: p.alt, position: index }; });

// 12-char base32 slug, no ambiguous characters (PLAN rule #4).
const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
let slug = '';
for (const byte of crypto.randomBytes(12)) slug += alphabet[byte % alphabet.length];

return [{
  json: {
    orderCode: orderCode,
    responseId: responseId,
    templateSlug: templateSlug,
    youtubeUrl: youtubeUrl,
    anniversaryDate: anniversaryRaw ? String(anniversaryRaw).slice(0, 10) : null,
    coupleNames: { a: nameA, b: nameB },
    coupleNamesJson: JSON.stringify({ a: nameA, b: nameB }),
    messages: messages,
    messagesJson: JSON.stringify(messages),
    photos: photos,
    photosJson: JSON.stringify(photos),
    slug: slug
  }
}];

const crypto = require('crypto');

// TODO(R2 signing): the "Upload to R2" node uses the n8n AWS (IAM) credential,
// which signs requests with SigV4. Cloudflare R2 needs the S3 endpoint and
// region "auto". If the AWS credential rejects region "auto", either sign the
// request in a Code node (AWS SigV4) or switch to a presigned PUT URL.

const source = $('Split Photos').item.json;
const binary = $input.first().binary || {};
const data = binary.data || binary[Object.keys(binary)[0]] || {};

const url = source.url || '';
const fileName = data.fileName || '';
const fromName = fileName.indexOf('.') !== -1 ? fileName.split('.').pop().toLowerCase() : '';
const cleanUrl = url.split('?')[0];
const fromUrl = cleanUrl.indexOf('.') !== -1 ? cleanUrl.split('.').pop().toLowerCase() : '';
let ext = fromName || fromUrl || 'jpg';
if (!/^[a-z0-9]{2,5}$/.test(ext)) ext = 'jpg';

const hash = crypto.createHash('sha1').update(String(url)).digest('hex').slice(0, 8);
const pageId = $('Insert Page').item.json.id;
const position = source.position || 0;
const r2Key = 'pages/' + pageId + '/' + position + '-' + hash + '.' + ext;

let publicBase = String($env.R2_PUBLIC_BASE_URL || '');
while (publicBase.charAt(publicBase.length - 1) === '/') publicBase = publicBase.slice(0, -1);

return [{
  json: { r2_key: r2Key, url: publicBase + '/' + r2Key, alt: source.alt || '', position: position },
  binary: binary
}];

// El QR lo genera la app Next.js en /api/qr/<slug> (error correction H, margin 4).
// Antes esto usaba require('qrcode'), que NO viene con n8n y exigía
// NODE_FUNCTION_ALLOW_EXTERNAL. Así no hay que instalar nada en el n8n compartido.
// El email lo consume igual: mantiene el nombre de campo `qrDataUrl`.
const base = String($env.NEXT_PUBLIC_BASE_URL || 'https://amor.uniongloss.com').replace(/\/+$/, '');
const slug = $('Insert Page').item.json.slug || '';
const publicUrl = base + '/s/' + slug;
const qrDataUrl = base + '/api/qr/' + slug;
return [{ json: { publicUrl: publicUrl, qrDataUrl: qrDataUrl } }];

const crypto = require('crypto');

function safeEqual(a, b) {
  const left = Buffer.from(String(a));
  const right = Buffer.from(String(b));
  if (left.length !== right.length) return false;
  return crypto.timingSafeEqual(left, right);
}

const item = $input.first();
const json = item.json || {};
const headers = json.headers || {};
const provided = headers['x-latido-secret'] || '';
const expected = $env.TALLY_WEBHOOK_SECRET || '';
const authorized = expected.length > 0 && safeEqual(provided, expected);

// TODO(latido): constant-time shared-secret check. Replace with the native
// signature scheme once confirmed against the provider docs.
return [{ json: Object.assign({}, json, { authorized }) }];

const order = $input.first().json;
const mapped = $('Map Tally Payload').item.json;
const payload = {
  order_id: order.id,
  slug: mapped.slug,
  template_slug: mapped.templateSlug || 'midnight-letter',
  couple_names: mapped.coupleNames || { a: '', b: '' },
  anniversary_date: mapped.anniversaryDate || null,
  youtube_url: mapped.youtubeUrl || null,
};
return [{ json: { pagePayload: JSON.stringify(payload) } }];

const item = $input.first().json;
const mapped = $('Map Tally Payload').item.json;
return [{ json: Object.assign({}, item, { photos: mapped.photos || [] }) }];
